CREATE TABLE operation_keys(tenant_id uuid NOT NULL,actor_id uuid NOT NULL,request_key varchar(100) NOT NULL,operation varchar(200) NOT NULL,request_hash varchar(64) NOT NULL,resource_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,actor_id,request_key,operation));
CREATE TABLE outbox_events(event_id uuid PRIMARY KEY,event_type varchar(80) NOT NULL,event_version int NOT NULL CHECK(event_version>0),tenant_id uuid NOT NULL,branch_id uuid,aggregate_id uuid NOT NULL,occurred_at timestamptz NOT NULL DEFAULT now(),correlation_id varchar(64) NOT NULL,payload jsonb NOT NULL,actor_id uuid NOT NULL,delivery_status varchar(20) NOT NULL DEFAULT 'PENDING' CHECK(delivery_status IN ('PENDING','DELIVERED')),attempts int NOT NULL DEFAULT 0 CHECK(attempts>=0),created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX pending_outbox ON outbox_events(created_at,event_id) WHERE delivery_status='PENDING';
CREATE INDEX tenant_outbox ON outbox_events(tenant_id,aggregate_id,occurred_at);


CREATE TABLE branch_commercial_settings(tenant_id uuid NOT NULL,branch_id uuid NOT NULL,currency char(3) NOT NULL CHECK(currency ~ '^[A-Z]{3}$'),labor_hourly_rate numeric(19,2) NOT NULL CHECK(labor_hourly_rate>=0),tax_rate numeric(7,4) NOT NULL CHECK(tax_rate BETWEEN 0 AND 100),legal_name varchar(200) NOT NULL,address varchar(1000) NOT NULL,tax_label varchar(100) NOT NULL DEFAULT 'Configured tax',registration_reference varchar(100),payment_required_before_delivery boolean NOT NULL DEFAULT true,version bigint NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,branch_id));
CREATE TABLE estimates(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,branch_id uuid NOT NULL,customer_id uuid NOT NULL,vehicle_id uuid NOT NULL,work_order_id uuid NOT NULL,series_id uuid NOT NULL,revision int NOT NULL CHECK(revision>0),status varchar(40) NOT NULL CHECK(status IN ('DRAFT','PENDING_CUSTOMER_APPROVAL','APPROVED','REJECTED','EXPIRED','SUPERSEDED','CANCELLED')),currency char(3) NOT NULL,subtotal numeric(19,2) NOT NULL CHECK(subtotal>=0),discount_total numeric(19,2) NOT NULL CHECK(discount_total>=0),tax_total numeric(19,2) NOT NULL CHECK(tax_total>=0),total numeric(19,2) NOT NULL CHECK(total>=0),tax_rate numeric(7,4) NOT NULL CHECK(tax_rate BETWEEN 0 AND 100),expires_at timestamptz NOT NULL,work_order_scope jsonb NOT NULL DEFAULT '[]'::jsonb,submitted_at timestamptz,decided_at timestamptz,note varchar(2000) NOT NULL,created_by uuid NOT NULL,version bigint NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),UNIQUE(tenant_id,series_id,revision),CHECK(total=subtotal-discount_total+tax_total));
CREATE UNIQUE INDEX one_current_estimate ON estimates(tenant_id,work_order_id) WHERE status IN ('DRAFT','PENDING_CUSTOMER_APPROVAL','APPROVED');
CREATE INDEX estimates_branch ON estimates(tenant_id,branch_id,created_at DESC,id);
CREATE TABLE estimate_items(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,estimate_id uuid NOT NULL,line_number int NOT NULL,item_type varchar(20) NOT NULL CHECK(item_type IN ('PART','LABOR','INSPECTION','SERVICE','MISC')),part_id uuid,description varchar(500) NOT NULL,quantity numeric(12,3) NOT NULL CHECK(quantity>0),unit_price numeric(19,2) NOT NULL CHECK(unit_price>=0),discount_percent numeric(7,4) NOT NULL CHECK(discount_percent BETWEEN 0 AND 100),net_amount numeric(19,2) NOT NULL CHECK(net_amount>=0),discount_amount numeric(19,2) NOT NULL CHECK(discount_amount>=0),tax_amount numeric(19,2) NOT NULL CHECK(tax_amount>=0),total numeric(19,2) NOT NULL CHECK(total>=0),source_reference jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(tenant_id,estimate_id) REFERENCES estimates(tenant_id,id),UNIQUE(tenant_id,estimate_id,line_number),CHECK((item_type='PART')=(part_id IS NOT NULL)));
CREATE TABLE estimate_approvals(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,estimate_id uuid NOT NULL,customer_id uuid NOT NULL,recipient varchar(254) NOT NULL,token_hash varchar(64) NOT NULL UNIQUE,expires_at timestamptz NOT NULL,status varchar(20) NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','APPROVED','REJECTED','REVOKED')),actor_id uuid,identity_issuer varchar(500),identity_subject varchar(500),decision_note varchar(1000),decided_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(tenant_id,estimate_id) REFERENCES estimates(tenant_id,id));
CREATE TABLE approval_mail_outbox(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,estimate_id uuid NOT NULL,recipient varchar(254) NOT NULL,encrypted_body text NOT NULL,status varchar(20) NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','SENT','FAILED')),attempts int NOT NULL DEFAULT 0,next_attempt_at timestamptz NOT NULL DEFAULT now(),sent_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(tenant_id,estimate_id) REFERENCES estimates(tenant_id,id));
CREATE TABLE invoice_counters(tenant_id uuid NOT NULL,branch_id uuid NOT NULL,year int NOT NULL,last_value bigint NOT NULL DEFAULT 0,PRIMARY KEY(tenant_id,branch_id,year));
CREATE TABLE invoices(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,branch_id uuid NOT NULL,customer_id uuid NOT NULL,vehicle_id uuid NOT NULL,work_order_id uuid NOT NULL,estimate_id uuid NOT NULL,invoice_number varchar(130),status varchar(20) NOT NULL CHECK(status IN ('DRAFT','ISSUED')),currency char(3) NOT NULL,subtotal numeric(19,2) NOT NULL,discount_total numeric(19,2) NOT NULL,tax_total numeric(19,2) NOT NULL,total numeric(19,2) NOT NULL CHECK(total>=0),snapshot jsonb NOT NULL,issued_at timestamptz,created_by uuid NOT NULL,version bigint NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),UNIQUE(tenant_id,invoice_number),UNIQUE(tenant_id,work_order_id),FOREIGN KEY(tenant_id,estimate_id) REFERENCES estimates(tenant_id,id),CHECK((status='ISSUED')=(issued_at IS NOT NULL)),CHECK(total=subtotal-discount_total+tax_total));
CREATE INDEX invoices_branch ON invoices(tenant_id,branch_id,created_at DESC,id);
CREATE TABLE invoice_items(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,invoice_id uuid NOT NULL,line_number int NOT NULL,snapshot jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(tenant_id,invoice_id) REFERENCES invoices(tenant_id,id),UNIQUE(tenant_id,invoice_id,line_number));
CREATE TABLE payments(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,branch_id uuid NOT NULL,invoice_id uuid NOT NULL,amount numeric(19,2) NOT NULL CHECK(amount>0),currency char(3) NOT NULL,method varchar(20) NOT NULL CHECK(method IN ('CASH','UPI','CARD','BANK','OTHER')),external_reference varchar(100) NOT NULL,record_type varchar(20) NOT NULL CHECK(record_type IN ('PAYMENT','REFUND')),reconciliation_status varchar(20) NOT NULL DEFAULT 'UNRECONCILED' CHECK(reconciliation_status IN ('UNRECONCILED','RECONCILED')),original_payment_id uuid,recorded_by uuid NOT NULL,reconciled_by uuid,reconciled_at timestamptz,note varchar(1000) NOT NULL,version bigint NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),UNIQUE(tenant_id,external_reference),FOREIGN KEY(tenant_id,invoice_id) REFERENCES invoices(tenant_id,id),FOREIGN KEY(tenant_id,original_payment_id) REFERENCES payments(tenant_id,id),CHECK((record_type='REFUND')=(original_payment_id IS NOT NULL)));
CREATE TABLE invoice_adjustments(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,invoice_id uuid NOT NULL,amount numeric(19,2) NOT NULL CHECK(amount>0),reason varchar(1000) NOT NULL,created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(tenant_id,invoice_id) REFERENCES invoices(tenant_id,id));
CREATE TABLE billing_audit_events(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,branch_id uuid NOT NULL,aggregate_id uuid NOT NULL,action varchar(80) NOT NULL,actor_id uuid NOT NULL,correlation_id varchar(64) NOT NULL,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX billing_audit ON billing_audit_events(tenant_id,branch_id,aggregate_id,created_at);
-- Defense in depth: submitted line snapshots and issued invoices cannot be edited even by accidental application SQL.
CREATE FUNCTION protect_estimate_item() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF EXISTS(SELECT 1 FROM billing.estimates WHERE tenant_id=OLD.tenant_id AND id=OLD.estimate_id AND status<>'DRAFT') THEN RAISE EXCEPTION 'Submitted estimate items are immutable'; END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END $$;
CREATE TRIGGER estimate_item_immutable BEFORE UPDATE OR DELETE ON estimate_items FOR EACH ROW EXECUTE FUNCTION protect_estimate_item();
CREATE FUNCTION protect_issued_invoice() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF OLD.status='ISSUED' THEN RAISE EXCEPTION 'Issued invoices are immutable; use an adjustment'; END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END $$;
CREATE TRIGGER invoice_immutable BEFORE UPDATE OR DELETE ON invoices FOR EACH ROW EXECUTE FUNCTION protect_issued_invoice();
CREATE FUNCTION protect_invoice_item() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF EXISTS(SELECT 1 FROM billing.invoices WHERE tenant_id=OLD.tenant_id AND id=OLD.invoice_id AND status='ISSUED') THEN RAISE EXCEPTION 'Issued invoice items are immutable'; END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END $$;
CREATE TRIGGER invoice_item_immutable BEFORE UPDATE OR DELETE ON invoice_items FOR EACH ROW EXECUTE FUNCTION protect_invoice_item();

CREATE TABLE invoice_documents(tenant_id uuid NOT NULL,invoice_id uuid NOT NULL,object_key varchar(500) NOT NULL,sha256 varchar(64) NOT NULL,byte_size bigint NOT NULL CHECK(byte_size>0),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,invoice_id),FOREIGN KEY(tenant_id,invoice_id) REFERENCES invoices(tenant_id,id));

CREATE FUNCTION protect_submitted_estimate() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF OLD.status<>'DRAFT' AND ROW(OLD.tenant_id,OLD.branch_id,OLD.customer_id,OLD.vehicle_id,OLD.work_order_id,OLD.series_id,OLD.revision,OLD.currency,OLD.subtotal,OLD.discount_total,OLD.tax_total,OLD.total,OLD.tax_rate,OLD.expires_at,OLD.note,OLD.work_order_scope) IS DISTINCT FROM ROW(NEW.tenant_id,NEW.branch_id,NEW.customer_id,NEW.vehicle_id,NEW.work_order_id,NEW.series_id,NEW.revision,NEW.currency,NEW.subtotal,NEW.discount_total,NEW.tax_total,NEW.total,NEW.tax_rate,NEW.expires_at,NEW.note,NEW.work_order_scope) THEN RAISE EXCEPTION 'Submitted estimate snapshot is immutable'; END IF; RETURN NEW; END $$;
CREATE TRIGGER estimate_snapshot_immutable BEFORE UPDATE ON estimates FOR EACH ROW EXECUTE FUNCTION protect_submitted_estimate();
CREATE FUNCTION protect_snapshot_insert() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF TG_TABLE_NAME='estimate_items' THEN IF EXISTS(SELECT 1 FROM billing.estimates WHERE tenant_id=NEW.tenant_id AND id=NEW.estimate_id AND status<>'DRAFT') THEN RAISE EXCEPTION 'Submitted estimate items are immutable'; END IF;
 ELSE IF EXISTS(SELECT 1 FROM billing.invoices WHERE tenant_id=NEW.tenant_id AND id=NEW.invoice_id AND status='ISSUED') THEN RAISE EXCEPTION 'Issued invoice items are immutable'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER estimate_item_insert BEFORE INSERT ON estimate_items FOR EACH ROW EXECUTE FUNCTION protect_snapshot_insert();
CREATE TRIGGER invoice_item_insert BEFORE INSERT ON invoice_items FOR EACH ROW EXECUTE FUNCTION protect_snapshot_insert();
